<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jaulas · Agencia Selena</title>
<style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b141a;color:#e9edef;font:16px system-ui}main{max-width:1200px;margin:auto;padding:24px}header{display:flex;align-items:center;gap:18px;flex-wrap:wrap}a{color:#00d6ae}h1{margin:10px 0}p,small{color:#aebac1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px;margin-top:24px}article{background:#111e24;border:1px solid #34464e;border-radius:14px;padding:20px}h2{font-size:20px}button{background:#00a884;color:white;border:0;border-radius:8px;padding:12px;cursor:pointer;font-weight:700}button:disabled{opacity:.5;cursor:default}label{display:flex;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid #27373e}input{accent-color:#00a884;width:18px;height:18px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}textarea{width:100%;min-height:240px;background:#0b141a;color:#e9edef;border:1px solid #34464e;border-radius:8px;padding:12px;font:14px/1.6 system-ui}.notice{min-height:24px;color:#71e9cd}</style>
<main><header><a href="index.php">← Volver</a><h1>Jaulas</h1><strong>AG SELENA</strong></header><p>Animales con más días sin salir. Se seleccionan los primeros 7 de cada tabla; puedes cambiar la selección antes de copiar.</p><p>Fuente: Resultados365 · Se consulta al abrir esta pantalla o al pulsar Actualizar. La lista muestra las filas disponibles en la fuente.</p><div class="grid" id="grid"></div></main>
<script type="module">
const lotteries={'lotto-activo':'Lotto Activo','guacharoactivo':'GuacharoActivo','selvaplus':'SelvaPlus','guacharito':'Guacharito','la-granjita':'La Granjita','lotto-activo-rd':'Lotto Activo RD','loto-activo-rd-int':'Loto Activo RD INT'};
for(const [id,name] of Object.entries(lotteries)){
 const card=document.createElement('article');card.innerHTML='<h2></h2><small class="time"></small><div class="rows"></div><div class="actions"><button class="copy" disabled>Copiar jaulas</button><button class="refresh">Actualizar</button></div><p class="notice" role="status"></p><textarea readonly aria-label="Reporte para copiar"></textarea><p><a target="_blank" rel="noopener noreferrer">Ver fuente</a></p>';
 card.querySelector('h2').textContent=name;card.querySelector('a').href=`https://resultados365.com/estadisticas/${id}/dias-sin-salir/`;document.querySelector('#grid').append(card);
 const area=card.querySelector('textarea'),rows=card.querySelector('.rows'),copy=card.querySelector('.copy'),refresh=card.querySelector('.refresh'),notice=card.querySelector('.notice');let data=[];let date='';
 function report(){const chosen=[...rows.querySelectorAll('input:checked')].map(i=>data[Number(i.value)]);area.value=chosen.length?`*${name}*\n*AG SELENA*\n${date}\n*Reporte de Animales Sin Salir*\n`+chosen.map(x=>`✅ ${x.animal}: ${x.dias} ${x.dias===1?'día':'días'}`).join('\n'):'';copy.disabled=!chosen.length;}
 async function load(){refresh.disabled=true;copy.disabled=true;data=[];rows.replaceChildren();area.value='';notice.textContent='Consultando…';card.querySelector('.time').textContent='';try{const r=await fetch('/jaulas_api.php?loteria='+id),j=await r.json();if(!r.ok||!j.ok||!j.animales.length)throw Error();data=j.animales;date=new Intl.DateTimeFormat('es-VE',{timeZone:'America/Caracas',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date(j.consultado_en));card.querySelector('.time').textContent='Consultado: '+date;data.forEach((x,i)=>{const label=document.createElement('label'),input=document.createElement('input'),text=document.createElement('span');input.type='checkbox';input.value=i;input.checked=i<7;text.textContent=`${x.animal}: ${x.dias} ${x.dias===1?'día':'días'}`;label.append(input,text);rows.append(label);input.addEventListener('change',report)});report();notice.textContent='';}catch{notice.textContent='No se pudo consultar. Pulsa Actualizar o revisa la fuente.';}finally{refresh.disabled=false;}}
 copy.onclick=async()=>{try{await navigator.clipboard.writeText(area.value);notice.textContent='Jaulas copiadas';}catch{area.focus();area.select();notice.textContent='Selecciona y copia el reporte con Ctrl+C o manteniendo pulsado.';}};refresh.onclick=load;load();
}
</script></html>
